class Solution:
    def combinationSum3(self, k: int, n: int) -> List[List[int]]:
        result: List[List[int]] = []
        path: List[int] = []

        def dfs(start: int, remaining_k: int, remaining_sum: int) -> None:
            if remaining_k == 0:
                if remaining_sum == 0:
                    result.append(path.copy())
                return
            if remaining_sum <= 0 or start > 9:
                return

            min_end = start + remaining_k - 1
            if min_end > 9:
                return
            min_sum = (start + min_end) * remaining_k // 2
            if min_sum > remaining_sum:
                return

            max_start = 10 - remaining_k
            max_sum = sum(range(max(start, max_start), 10))
            if max_sum < remaining_sum:
                return

            for x in range(start, 10):
                if x > remaining_sum:
                    break
                path.append(x)
                dfs(x + 1, remaining_k - 1, remaining_sum - x)
                path.pop()

        dfs(1, k, n)
        return result

