#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

static int *path;
static int pathLen;
static int **result;
static int *columnSizes;
static int resultSize;

static void dfs(int start, int remainingK, int remainingSum) {
    if (remainingK == 0) {
        if (remainingSum == 0) {
            int *row = (int *)malloc(pathLen * sizeof(int));
            for (int i = 0; i < pathLen; ++i) row[i] = path[i];
            result[resultSize] = row;
            columnSizes[resultSize] = pathLen;
            ++resultSize;
        }
        return;
    }
    if (remainingSum <= 0 || start > 9) return;

    int minEnd = start + remainingK - 1;
    if (minEnd > 9) return;
    int minSum = (start + minEnd) * remainingK / 2;
    if (minSum > remainingSum) return;

    int maxStart = 10 - remainingK;
    int maxSum = 0;
    int from = start > maxStart ? start : maxStart;
    for (int x = from; x <= 9; ++x) maxSum += x;
    if (maxSum < remainingSum) return;

    for (int x = start; x <= 9; ++x) {
        if (x > remainingSum) break;
        path[pathLen++] = x;
        dfs(x + 1, remainingK - 1, remainingSum - x);
        --pathLen;
    }
}

int** combinationSum3(int k, int n, int* returnSize, int** returnColumnSizes) {
    // At most C(9,4)=126 valid combinations for any k in [2,9].
    result = (int **)malloc(126 * sizeof(int *));
    columnSizes = (int *)malloc(126 * sizeof(int));
    path = (int *)malloc(k * sizeof(int));
    pathLen = 0;
    resultSize = 0;

    dfs(1, k, n);

    *returnSize = resultSize;
    *returnColumnSizes = columnSizes;
    free(path);
    return result;
}

