class Solution {
    public List<List<Integer>> combinationSum3(int k, int n) {
        List<List<Integer>> result = new ArrayList<>();
        List<Integer> path = new ArrayList<>();
        dfs(1, k, n, path, result);
        return result;
    }

    private void dfs(int start, int remainingK, int remainingSum,
                     List<Integer> path, List<List<Integer>> result) {
        if (remainingK == 0) {
            if (remainingSum == 0) result.add(new ArrayList<>(path));
            return;
        }
        if (remainingSum <= 0 || start > 9) return;

        int minEnd = start + remainingK - 1;
        if (minEnd > 9) return;
        int minSum = (start + minEnd) * remainingK / 2;
        if (minSum > remainingSum) return;

        int maxStart = 10 - remainingK;
        int maxSum = 0;
        for (int x = Math.max(start, maxStart); x <= 9; x++) maxSum += x;
        if (maxSum < remainingSum) return;

        for (int x = start; x <= 9; x++) {
            if (x > remainingSum) break;
            path.add(x);
            dfs(x + 1, remainingK - 1, remainingSum - x, path, result);
            path.remove(path.size() - 1);
        }
    }
}

